// Проверка секрета и валидация payload.
// ЗАМЕНИТЕ SECRET на значение n8n_webhook_secret из config.php.
const SECRET = 'ЗАМЕНИТЕ-НА-СЕКРЕТ';
const req = $input.first().json;
const headers = req.headers || {};
if ((headers['x-auth-token'] || '') !== SECRET) {
  throw new Error('FORBIDDEN: неверный X-Auth-Token');
}
const body = req.body || {};
const reviewer = body.reviewer || {};
const items = Array.isArray(body.items) ? body.items : [];
if (!reviewer.bitrix_user_id || !items.length) {
  throw new Error('VALIDATION: reviewer/items');
}
for (const it of items) {
  if (!it.call_key) throw new Error('VALIDATION: call_key');
  if (!['CONFIRM', 'CHANGE_SCORE'].includes(it.action)) throw new Error('VALIDATION: action');
  if (it.action === 'CHANGE_SCORE') {
    const s = Number(it.new_score);
    if (!(s >= 1 && s <= 5)) throw new Error('VALIDATION: new_score');
    if (!it.comment) throw new Error('VALIDATION: comment обязателен при CHANGE_SCORE');
  }
}
return [{ json: { reviewer, items } }];

// Находим строки по call_key, проверяем review_status, готовим записи.
// Требуемые колонки основного листа: review_status, review_score, reviewed_by, reviewed_at.
const sheet = $('Read Main Sheet').first().json;
const { reviewer, items } = $('Validate').first().json;
const rows = sheet.values || [];
if (!rows.length) throw new Error('Основной лист пуст');
const header = rows[0].map(String);
const col = (name) => header.indexOf(name);
const iKey = col('call_key');
const need = ['review_status', 'review_score', 'reviewed_by', 'reviewed_at'];
for (const n of need) if (col(n) < 0) throw new Error('Нет колонки ' + n + ' на листе «Записи звонков» — добавьте её в HEADERS Apps Script и пересканируйте.');

const toLetter = (i) => { let s = ''; i += 1; while (i > 0) { const m = (i - 1) % 26; s = String.fromCharCode(65 + m) + s; i = Math.floor((i - 1) / 26); } return s; };
const byKey = new Map();
rows.forEach((r, idx) => { if (idx > 0 && r[iKey]) byKey.set(String(r[iKey]).trim(), { rowNumber: idx + 1, row: r }); });

const now = new Date();
const pad = (n) => String(n).padStart(2, '0');
const ts = `${now.getFullYear()}-${pad(now.getMonth()+1)}-${pad(now.getDate())} ${pad(now.getHours())}:${pad(now.getMinutes())}:${pad(now.getSeconds())}`;

const journalRows = [];
const valueRanges = [];
const results = [];
for (const it of items) {
  const found = byKey.get(it.call_key);
  if (!found) { results.push({ call_key: it.call_key, ok: false, code: 'NOT_FOUND' }); continue; }
  const status = String(found.row[col('review_status')] || '').trim();
  if (status) { results.push({ call_key: it.call_key, ok: false, code: 'ALREADY_REVIEWED' }); continue; }
  const snap = it.snapshot || {};
  journalRows.push([
    ts, it.call_key, String(reviewer.bitrix_user_id), reviewer.name || '', it.action,
    snap.ai_score ?? '', it.action === 'CHANGE_SCORE' ? it.new_score : '', it.comment || '',
    snap.group ?? '', snap.operator_name ?? '', snap.call_datetime ?? '', snap.client_phone ?? ''
  ]);
  const rangeRow = found.rowNumber;
  valueRanges.push({
    range: `Записи звонков!${toLetter(col('review_status'))}${rangeRow}:${toLetter(col('review_status'))}${rangeRow}`,
    values: [[it.action === 'CONFIRM' ? 'CONFIRMED' : 'SCORE_CHANGED']]
  });
  valueRanges.push({ range: `Записи звонков!${toLetter(col('review_score'))}${rangeRow}`, values: [[it.action === 'CHANGE_SCORE' ? it.new_score : '']] });
  valueRanges.push({ range: `Записи звонков!${toLetter(col('reviewed_by'))}${rangeRow}`, values: [[String(reviewer.bitrix_user_id)]] });
  valueRanges.push({ range: `Записи звонков!${toLetter(col('reviewed_at'))}${rangeRow}`, values: [[ts]] });
  results.push({ call_key: it.call_key, ok: true });
}
return [{ json: { journalRows, valueRanges, results, hasWrites: journalRows.length > 0 } }];
